'use client';
import { useEffect, useRef, useState, type ReactNode } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';
import { useInView, useStudioMotion } from '../../../motion';
import { resolveParams, type EffectMeta, type ParamValues } from '../../../types';
import VariableWeightWave from '../../../effects/variable-weight-wave';
import { meta as waveMeta } from '../../../effects/variable-weight-wave/meta';
import ScrambleDecode from '../../../effects/scramble-decode';
import { meta as scrambleMeta } from '../../../effects/scramble-decode/meta';
import SplitLineReveal from '../../../effects/split-line-reveal';
import { meta as splitMeta } from '../../../effects/split-line-reveal/meta';
import KineticMarquee from '../../../effects/kinetic-marquee';
import { meta as marqueeMeta } from '../../../effects/kinetic-marquee/meta';
import { AREAS, Coastline } from './Coastline';
import { ForceScale, Winds } from './Winds';
import s from './styles.module.css';

if (typeof window !== 'undefined') gsap.registerPlugin(ScrollTrigger, useGSAP);

/** Every recipe param from its meta (defaults), then this demo's overrides. */
const recipe = <T,>(m: EffectMeta, overrides: ParamValues = {}): T => resolveParams(m.params, overrides) as unknown as T;

const DIAL = { min: 87.5, max: 108, from: 89.1, station: 97.4 };
const fx = (f: number): number => ((f - DIAL.min) / (DIAL.max - DIAL.min)) * 1000;
const TICKS = Array.from({ length: 42 }, (_, i) => DIAL.min + i * 0.5);

/** Mounts a time-based recipe only once it is well inside the viewport, so its entrance is actually seen. */
function OnView({ children, placeholder, className }: { children: ReactNode; placeholder: ReactNode; className?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const near = useInView(ref, { amount: 0.45 });
  const { reduced } = useStudioMotion();
  return <div ref={ref} className={className}>{near || reduced ? children : placeholder}</div>;
}

function Cue({ time, children, className, labelledBy }: { time: string; children: ReactNode; className?: string; labelledBy?: string }) {
  return (
    <section className={`${s.cue} ${className ?? ''}`} aria-labelledby={labelledBy}>
      <p className={s.time} aria-hidden="true">{time}</p>
      <div className={s.cueBody}>{children}</div>
    </section>
  );
}

export default function KineticTypography() {
  const { reduced } = useStudioMotion();
  const [paused, setPaused] = useState(false);
  const moving = !reduced && !paused;
  const root = useRef<HTMLDivElement>(null);
  const hero = useRef<HTMLElement>(null);
  const needle = useRef<SVGGElement>(null);
  const readout = useRef<SVGTextElement>(null);
  const marquee = useRef<HTMLDivElement>(null);

  // Tuning: the dial needle sweeps onto the station as the hero scrolls away (scrubbed, so it is reversible).
  useGSAP(() => {
    const el = root.current;
    const h = hero.current;
    const paint = (f: number) => {
      needle.current?.setAttribute('transform', `translate(${fx(f).toFixed(1)} 0)`);
      if (readout.current) readout.current.textContent = f.toFixed(1);
    };
    if (reduced || !el || !h) { paint(DIAL.station); return; }
    const state = { f: DIAL.from };
    paint(state.f);
    gsap.to(state, { f: DIAL.station, ease: 'none', onUpdate: () => paint(state.f), scrollTrigger: { trigger: h, start: 'top top+=44', end: 'bottom 40%', scrub: 0.4 } });

    // Every trigger on the page (here and in the wind list) depends on fonts and on the frame width.
    let width = el.clientWidth;
    let timer = 0;
    const ro = new ResizeObserver(() => {
      if (el.clientWidth === width) return;
      width = el.clientWidth;
      window.clearTimeout(timer);
      timer = window.setTimeout(() => ScrollTrigger.refresh(), 140);
    });
    ro.observe(el);
    let alive = true;
    void document.fonts?.ready.then(() => { if (alive) ScrollTrigger.refresh(); });
    return () => { alive = false; ro.disconnect(); window.clearTimeout(timer); paint(DIAL.station); };
  }, { scope: root, dependencies: [reduced], revertOnUpdate: true });

  // One pause control for the whole piece: the marquee recipe keeps its own button, so mirror the state onto it.
  useEffect(() => {
    const btn = marquee.current?.querySelector<HTMLButtonElement>('button[aria-pressed]');
    if (btn && (btn.getAttribute('aria-pressed') === 'true') !== paused) btn.click();
  }, [paused, reduced]);

  return (
    <div ref={root} className={s.root} data-paused={paused || undefined}>
      <div className={s.bar}>
        <p className={s.station}>
          <span className={s.lamp} aria-hidden="true" />
          <span className={s.stationName}>Radio Haar</span>
          <span>97.4 FM</span>
          <span className={s.fict}>fictional station</span>
        </p>
        {reduced ? (
          <p className={s.barNote}>Reduced motion: all type is still</p>
        ) : (
          <button type="button" className={s.pause} aria-pressed={paused} onClick={() => setPaused((p) => !p)}>
            <svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true" focusable="false">
              {paused ? <path d="M3 1.5v9l7.5-4.5z" fill="currentColor" /> : <path d="M2.5 1.5h2.5v9H2.5zM7 1.5h2.5v9H7z" fill="currentColor" />}
            </svg>
            Pause motion
          </button>
        )}
      </div>

      <section ref={hero} className={`${s.cue} ${s.hero}`}>
        <p className={s.time} aria-hidden="true">00:48:00</p>
        <div className={s.cueBody}>
          <p className={s.kicker}>Inner waters <span aria-hidden="true">·</span> read at 00:48 and 05:20 <span aria-hidden="true">·</span> sample content</p>
          <div className={s.wave}>
            <VariableWeightWave params={recipe(waveMeta, { text: 'The night forecast', minWeight: 250, maxWeight: 800, radius: 1.2, squeeze: true, idle: !paused })} />
          </div>
          <p className={s.voice}>Read slowly, for the boats that are still out.</p>
          <svg className={s.dial} viewBox="-12 0 1024 70" aria-hidden="true" focusable="false">
            <path className={s.dialRule} d="M0 40H1000" />
            {TICKS.map((f) => {
              const major = Number.isInteger(f) && f % 4 === 0;
              return <path key={f} className={major ? s.tickMajor : s.tick} d={`M${fx(f).toFixed(1)} ${major ? 22 : 30}V40`} />;
            })}
            {TICKS.filter((f) => Number.isInteger(f) && f % 4 === 0).map((f) => <text key={f} className={s.dialNum} x={fx(f)} y="60">{f}</text>)}
            <g ref={needle} className={s.needle} transform={`translate(${fx(DIAL.station).toFixed(1)} 0)`}>
              <path d="M0 6V44" />
              <circle cy="6" r="4" />
              <text ref={readout} className={s.readout} x="10" y="14">{DIAL.station.toFixed(1)}</text>
            </g>
          </svg>
        </div>
      </section>

      <Cue time="00:48:06" className={s.tune} labelledBy="kt-tune">
        <h2 id="kt-tune" className={s.label}>Tuning in</h2>
        <OnView className={s.decode} placeholder={<p className={s.decodeHold}>Ossel coastguard, 00:48. The forecast for the inner waters for the next 24 hours.</p>}>
          <ScrambleDecode params={recipe(scrambleMeta, { text: 'Ossel coastguard, 00:48. The forecast for the inner waters for the next 24 hours.', duration: 1500, churn: 48, glyphs: 'alphanumeric', seed: 31 })} />
        </OnView>
      </Cue>

      <Cue time="00:48:21" labelledBy="kt-areas">
        <h2 id="kt-areas" className={s.label}>Sea areas, in the order they are read</h2>
        <div className={s.chartFrame}><Coastline moving={moving} /></div>
        <p className={s.areaList}>{AREAS.join(' · ')}</p>
      </Cue>

      <Cue time="00:48:40" labelledBy="kt-wind">
        <h2 id="kt-wind" className={s.label}>Wind</h2>
        <Winds reduced={reduced} />
        <ForceScale />
      </Cue>

      <Cue time="00:49:32" className={s.state}>
        <p className={s.label}>Sea state and visibility</p>
        <OnView placeholder={<h2 className={s.stateHold}>Rough, occasionally very rough. Visibility good, becoming poor in haar.</h2>}>
          <SplitLineReveal params={recipe(splitMeta, { text: 'Rough, occasionally very rough. Visibility good, becoming poor in haar.', stagger: 52, duration: 760, rise: 115, skew: true })} />
        </OnView>
      </Cue>

      <Cue time="00:49:50" className={s.gale} labelledBy="kt-gale">
        <h2 id="kt-gale" className={s.label}>Gale warnings in force</h2>
        <div ref={marquee} className={s.marquee}>
          <KineticMarquee params={recipe(marqueeMeta, { text: 'Tarrow Deep / The Dray / Low Marra / Fennick, later', speed: 64, reactivity: 1.1, skew: 8, direction: 'left', pauseOnHover: true, label: '' })} />
        </div>
      </Cue>

      <Cue time="00:50:14" className={s.end} labelledBy="kt-end">
        <h2 id="kt-end" className={s.endLine}>That was the forecast.</h2>
        <p className={s.next}>The next one is read at 05:20, after the news.</p>
        <p className={s.fine}>Radio Haar, its coast and its sea areas are fictional; every wind, sea state and time on this page is sample content, not a forecast.</p>
      </Cue>
    </div>
  );
}

'use client';
import { useEffect, useId, useRef } from 'react';
import { useRafLoop } from '../../../motion';
import s from './styles.module.css';

export const AREAS = ['Skerrow', 'Brannock', 'Hollin Bank', 'Tarrow Deep', 'The Dray', 'Fennick', 'Low Marra', 'Ossel'] as const;

const COAST = 'M-20 120C80 110 120 190 200 170S300 90 380 140S470 250 560 220S660 150 720 210S800 330 900 300S1010 240 1060 320S1150 420 1220 400';
const TEXT_LINE = 'M-20 196C90 186 130 256 210 241S310 171 390 211S480 316 570 291S670 226 730 281S810 396 910 371S1020 311 1070 391S1160 486 1220 471';
const DEPTH_A = 'M-20 286C120 276 200 330 300 316S470 300 560 356S760 420 900 430S1100 470 1220 540';
const DEPTH_B = 'M-20 392C160 380 260 420 380 420S560 440 680 480S900 540 1000 580';
const SOUNDINGS: readonly [number, number, string][] = [
  [80, 330, '14'], [250, 370, '22'], [420, 352, '19'], [620, 420, '31'], [760, 470, '38'], [960, 500, '44'],
  [520, 470, '27'], [330, 470, '25'], [140, 480, '18'], [1110, 520, '47'], [880, 410, '29'], [690, 330, '16'],
];
const TEXT = AREAS.join('  ·  ');
const LAND = `${COAST}L1220 -20L-20 -20Z`;

/** Sea-area names set along the coast on an SVG textPath. They drift like a slow ticker (pausable) and borrow speed from scrolling. */
export function Coastline({ moving }: { moving: boolean }) {
  const ids = useId();
  const pathId = `${ids}-coast-text`;
  const root = useRef<SVGSVGElement>(null);
  const textEl = useRef<SVGTextElement>(null);
  const tp = useRef<SVGTextPathElement>(null);
  const sim = useRef({ x: 0, copy: 0, impulse: 0, boost: 0, lastY: 0 });

  // One copy's length (the text holds two copies so the loop is seamless); re-measured once fonts arrive.
  useEffect(() => {
    let alive = true;
    const measure = () => { if (alive && textEl.current) sim.current.copy = textEl.current.getComputedTextLength() / 2; };
    measure();
    void document.fonts?.ready.then(measure);
    return () => { alive = false; };
  }, [moving]);

  useEffect(() => {
    if (!moving) return;
    sim.current.lastY = window.scrollY;
    const onScroll = () => { const y = window.scrollY; sim.current.impulse += y - sim.current.lastY; sim.current.lastY = y; };
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, [moving]);

  useRafLoop(root, (dt) => {
    const m = sim.current;
    if (dt <= 0 || !m.copy || !tp.current) return;
    const v = Math.max(-900, Math.min(900, (m.impulse / dt) * 0.6));
    m.impulse = 0;
    m.boost += (v - m.boost) * (1 - Math.exp(-dt * (Math.abs(v) > Math.abs(m.boost) ? 8 : 2.5)));
    m.x = (((m.x + (32 + Math.abs(m.boost)) * dt) % m.copy) + m.copy) % m.copy;
    tp.current.setAttribute('startOffset', (-m.x).toFixed(1));
  }, moving);

  useEffect(() => { if (!moving) { sim.current.x = 0; tp.current?.setAttribute('startOffset', '0'); } }, [moving]);

  return (
    <svg ref={root} className={s.chart} viewBox="0 0 1200 560" role="img" aria-labelledby={`${ids}-t ${ids}-d`} focusable="false" data-moving={moving || undefined}>
      <title id={`${ids}-t`}>Chart of the inner waters (fictional)</title>
      <desc id={`${ids}-d`}>The sea areas are read in order along the coast: {AREAS.join(', ')}.</desc>
      <defs>
        <path id={pathId} d={TEXT_LINE} />
        <clipPath id={`${ids}-land`}><path d={LAND} /></clipPath>
      </defs>
      <path className={s.land} d={LAND} />
      <g className={s.hatch} clipPath={`url(#${ids}-land)`}>
        {Array.from({ length: 22 }, (_, i) => <path key={i} d={`M${i * 64} -20l-460 480`} />)}
      </g>
      <path className={s.coast} d={COAST} />
      <path className={s.depth} d={DEPTH_A} />
      <path className={s.depth} d={DEPTH_B} />
      {SOUNDINGS.map(([x, y, n]) => <text key={`${x}-${y}`} className={s.sounding} x={x} y={y}>{n}</text>)}
      <g className={s.rose} transform="translate(1090 150)">
        <circle r="34" />
        <path d="M0 -48V48M-48 0H48M-24 -24L24 24M24 -24L-24 24" />
        <path className={s.roseN} d="M0 -46L7 -8H-7Z" />
        <text x="-5" y="-54">N</text>
      </g>
      <text ref={textEl} className={s.areaText}>
        <textPath ref={tp} href={`#${pathId}`} startOffset="0">{moving ? `${TEXT}  ·  ${TEXT}  ·  ` : TEXT}</textPath>
      </text>
    </svg>
  );
}

/*
 * Radio Haar — the night forecast as a broadcast transcript. Type is the only material: a timecode gutter,
 * mono for the broadcast data, Instrument Serif for the presenter's voice and Bricolage Grotesque with all
 * three axes for everything that moves. The gallery only loads Bricolage's wght axis, so this demo declares
 * the local "standard" cut (wght + wdth + opsz) under its own family name.
 */
.root {
  --kt-pad: clamp(16px, 4cqi, 56px);
  --kt-axes: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  position: relative;
  overflow-x: clip;
  background: var(--s3-bg, #f3f0e8);
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  font-synthesis: none;
}

/* ── On-air bar ─────────────────────────────────────────────── */
.bar {
  position: sticky;
  top: 44px;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 52px;
  padding: 0 var(--kt-pad);
  background: var(--s3-bg, #f3f0e8);
  border-bottom: 1px solid var(--s3-line, #11110f24);
}
.station, .barNote {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.barNote { color: var(--s3-ink-muted, #5c5a52); text-align: end; }
.lamp { width: 9px; height: 9px; border-radius: 50%; background: var(--s3-signal, #bf2f09); box-shadow: 0 0 0 3px color-mix(in oklab, var(--s3-signal, #bf2f09) 22%, transparent); }
.stationName { font-family: var(--kt-axes); font-size: 1.0625rem; font-weight: 760; font-stretch: 80%; letter-spacing: -0.01em; text-transform: none; }
.fict { color: var(--s3-ink-muted, #5c5a52); }
@container (max-width: 30rem) { .fict { display: none; } }
.pause {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid var(--s3-line-strong, #11110f);
  border-radius: 999px;
  background: transparent;
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
}
.pause:hover, .pause[aria-pressed='true'] { background: var(--s3-ink, #11110f); color: var(--s3-bg, #f3f0e8); }
.pause:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 3px; }

/* ── Transcript cues: timecode gutter + body ────────────────── */
.cue {
  position: relative;
  display: grid;
  gap: 14px;
  padding: clamp(64px, 10cqi, 150px) var(--kt-pad);
  border-bottom: 1px solid var(--s3-line, #11110f24);
}
@container (min-width: 56rem) {
  .cue { grid-template-columns: 7.5rem minmax(0, 1fr); column-gap: clamp(24px, 3cqi, 48px); }
}
.time {
  position: sticky;
  top: calc(44px + 52px + 24px);
  align-self: start;
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.75rem;
  letter-spacing: 0.06em;
  font-variant-numeric: tabular-nums;
  color: var(--s3-ink-muted, #5c5a52);
}
.cueBody { display: grid; gap: clamp(18px, 2.6cqi, 36px); min-width: 0; }
.label, .kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--s3-ink, #11110f);
}
.label::before { content: ''; flex: none; width: 28px; height: 1px; background: var(--s3-signal, #bf2f09); }
.kicker { display: block; line-height: 1.6; color: var(--s3-ink-muted, #5c5a52); }
@container (max-width: 56rem) { .time { position: static; } }

/* Hero: the weight-wave recipe, set left and large */
.hero { min-height: calc(100svh - 44px - 53px); align-content: end; padding-top: clamp(40px, 6cqi, 96px); padding-bottom: clamp(32px, 4cqi, 56px); }
.wave > div { justify-items: start; padding: 0; gap: 18px; }
.wave h2 {
  font-family: var(--kt-axes);
  font-size: clamp(3.3rem, 0.4rem + 14.6cqi, 15.5rem);
  line-height: 0.86;
  letter-spacing: -0.035em;
  text-align: start;
}
.wave p { justify-content: flex-start; }
@container (max-width: 40rem) { .hero { min-height: 0; padding-top: 72px; } }
@container (max-width: 40rem) { .wave h2 { font-size: clamp(3.3rem, 22cqi, 6rem); } }
.voice {
  justify-self: end;
  max-width: 21ch;
  margin: 0;
  font-family: var(--s3-font-serif, Georgia, serif);
  font-size: clamp(1.5rem, 0.9rem + 2.2cqi, 2.9rem);
  font-style: italic;
  line-height: 1.08;
  text-align: end;
  text-wrap: balance;
}
.dial { display: block; width: 100%; height: auto; margin-top: clamp(8px, 2cqi, 24px); }
.dialRule { stroke: var(--s3-ink, #11110f); stroke-width: 1; }
.tick { stroke: var(--s3-ink-muted, #5c5a52); stroke-width: 1; }
.tickMajor { stroke: var(--s3-ink, #11110f); stroke-width: 1.4; }
.dialNum { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 12px; text-anchor: middle; fill: var(--s3-ink-muted, #5c5a52); }
.needle path { stroke: var(--s3-signal, #bf2f09); stroke-width: 2.2; }
.needle circle { fill: var(--s3-signal, #bf2f09); }
.readout { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 14px; font-weight: 600; fill: var(--s3-signal, #bf2f09); }

/* Tuning in: the scramble-decode recipe, left-aligned and wider */
.decode > div { width: 100%; max-width: 64rem; margin: 0; }
.decodeHold { min-height: 12rem; margin: 0; opacity: 0; }

/* Sea areas chart */
.chartFrame { overflow: clip; margin-inline: calc(-1 * var(--kt-pad)); }
.chart { display: block; width: 100%; height: auto; }
@container (max-width: 40rem) { .chart { width: 190%; margin-left: -42%; } }
.land { fill: var(--s3-surface-2, #e9e5da); }
.hatch path { stroke: var(--s3-line, #11110f24); stroke-width: 1.2; }
.coast { fill: none; stroke: var(--s3-ink, #11110f); stroke-width: 1.6; stroke-linejoin: round; }
.depth { fill: none; stroke: var(--s3-ink-muted, #5c5a52); stroke-width: 1; stroke-dasharray: 2 7; }
.sounding { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 13px; font-style: italic; fill: var(--s3-ink-muted, #5c5a52); }
.rose circle, .rose path { fill: none; stroke: var(--s3-ink-muted, #5c5a52); stroke-width: 1; }
.rose .roseN { fill: var(--s3-signal, #bf2f09); stroke: none; }
.rose text { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 13px; fill: var(--s3-ink, #11110f); }
.areaText { font-family: var(--kt-axes); font-size: 26px; font-weight: 600; font-stretch: 88%; letter-spacing: 0.01em; fill: var(--s3-ink, #11110f); }
.chart[data-moving] .areaText { font-size: 36px; }
.areaList { margin: 0; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }

/* Wind: one row per area; the axes are custom properties written by the scrubbed timeline */
.winds { display: grid; gap: clamp(10px, 1.6cqi, 22px); margin: 0; padding: 0; list-style: none; transform-origin: 0 50%; }
.windRow { display: grid; gap: 6px 24px; align-items: baseline; padding-bottom: clamp(10px, 1.4cqi, 18px); border-bottom: 1px solid var(--s3-line, #11110f24); }
@container (min-width: 48rem) { .windRow { grid-template-columns: minmax(0, 1fr) minmax(13rem, 21rem); } }
.windArea, .scaleGlyph {
  font-family: var(--kt-axes);
  font-weight: var(--wght, 400);
  font-stretch: calc(var(--wdth, 100) * 1%);
  font-variation-settings: 'opsz' var(--opsz, 14);
}
.windArea { font-size: clamp(2.6rem, 0.6rem + 8.4cqi, 9rem); line-height: 0.95; letter-spacing: -0.02em; white-space: nowrap; }
.windText {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.8125rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.windText[data-gale] { color: var(--s3-signal, #bf2f09); font-weight: 600; }
.arrow { flex: none; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transform-box: fill-box; transform-origin: center; }
.scale { display: grid; gap: 12px; margin: 0; }
.scaleRow { display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); border-block: 1px solid var(--s3-line, #11110f24); }
.scaleCell { display: grid; justify-items: start; gap: 4px; padding: 10px 6px 8px; border-inline-end: 1px solid var(--s3-line, #11110f24); }
.scaleCell:last-child { border-inline-end: 0; }
.scaleGlyph { font-size: clamp(1.4rem, 4cqi, 3.4rem); line-height: 1; }
.scaleNum { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.625rem; letter-spacing: 0.06em; color: var(--s3-ink-muted, #5c5a52); }
.scaleCap { max-width: 62ch; margin: 0; font-size: 0.875rem; line-height: 1.5; color: var(--s3-ink-muted, #5c5a52); }

/* Sea state: split-line-reveal, set condensed and heavy */
.state h2, .stateHold {
  max-width: 15ch;
  margin: 0;
  font-family: var(--kt-axes);
  font-size: clamp(2.5rem, 0.8rem + 7.2cqi, 7.75rem);
  font-weight: 760;
  font-stretch: 80%;
  line-height: 0.94;
  letter-spacing: -0.03em;
  color: var(--s3-ink, #11110f);
}
.stateHold { opacity: 0; }

/* Gale warnings: the marquee recipe (its header label is turned off with label: '' — this section's heading names it). */
.gale .cueBody { gap: 4px; }
.marquee { margin-inline: calc(-1 * var(--kt-pad)); }
.marquee li { font-family: var(--kt-axes); font-weight: 780; font-stretch: 78%; }

/* Sign-off: still. */
.end { border-bottom: 0; }
.endLine {
  max-width: 11ch;
  margin: 0;
  font-family: var(--s3-font-serif, Georgia, serif);
  font-size: clamp(3rem, 1rem + 9.5cqi, 10.5rem);
  font-weight: 400;
  line-height: 0.9;
  letter-spacing: -0.03em;
}
.next { margin: 0; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.8125rem; letter-spacing: 0.06em; text-transform: uppercase; }
.fine { max-width: 60ch; margin: 0; padding-top: 14px; border-top: 1px solid var(--s3-line, #11110f24); font-size: 0.8125rem; line-height: 1.55; color: var(--s3-ink-muted, #5c5a52); }

'use client';
import { useRef, type CSSProperties } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';
import s from './styles.module.css';

if (typeof window !== 'undefined') gsap.registerPlugin(ScrollTrigger, useGSAP);

/** Sample forecast (fictional areas). `from` is the compass bearing the wind blows from. */
const WINDS = [
  { area: 'Skerrow', wind: 'Southwest 3 or 4', force: 3.5, from: 225 },
  { area: 'Brannock', wind: 'Southwest 4, increasing 6', force: 5, from: 225 },
  { area: 'Hollin Bank', wind: 'South 5 to 7', force: 6, from: 180 },
  { area: 'Tarrow Deep', wind: 'Southerly gale 8', force: 8, from: 180 },
  { area: 'The Dray', wind: 'Southeast 7 to severe gale 9', force: 9, from: 135 },
  { area: 'Fennick', wind: 'Variable 2, becoming west 4', force: 2.5, from: 270 },
] as const;

/** Wind force → variable axes: calm is light, wide and text-sized in optics; a gale is heavy, narrow, display-cut. */
export const axes = (force: number) => ({ wght: Math.round(220 + force * 64), wdth: +(100 - force * 2.6).toFixed(1), opsz: +(12 + force * 9.3).toFixed(1) });
const CALM = { wght: 300, wdth: 100, opsz: 12 };
const vars = (a: { wght: number; wdth: number; opsz: number }) => ({ '--wght': a.wght, '--wdth': a.wdth, '--opsz': a.opsz }) as CSSProperties;

export function Winds({ reduced }: { reduced: boolean }) {
  const root = useRef<HTMLOListElement>(null);

  useGSAP(() => {
    const list = root.current;
    if (reduced || !list) return;
    const rows = gsap.utils.toArray<HTMLElement>('[data-row]', list);
    // Each row swells from calm to its force as it rises through the lower half of the screen (scrubbed).
    const tl = gsap.timeline({
      defaults: { ease: 'none' },
      scrollTrigger: { trigger: list, start: 'top 82%', end: 'bottom 48%', scrub: 0.5, invalidateOnRefresh: true },
    });
    rows.forEach((row, i) => {
      const a = axes(Number(row.dataset.force));
      tl.fromTo(row, { '--wght': CALM.wght, '--wdth': CALM.wdth, '--opsz': CALM.opsz }, { '--wght': a.wght, '--wdth': a.wdth, '--opsz': a.opsz, duration: 1 }, i * 0.6);
    });
    // Gusts: scroll velocity leans the whole list for a moment, then it settles back upright.
    const lean = gsap.quickTo(list, 'skewX', { duration: 0.45, ease: 'power3.out' });
    const settle = gsap.delayedCall(0.14, () => lean(0)).pause();
    ScrollTrigger.create({
      trigger: list,
      start: 'top bottom',
      end: 'bottom top',
      onUpdate: (self) => { lean(gsap.utils.clamp(-7, 7, self.getVelocity() / -320)); settle.restart(true); },
    });
  }, { scope: root, dependencies: [reduced], revertOnUpdate: true });

  return (
    <ol ref={root} className={s.winds}>
      {WINDS.map((w) => (
        <li key={w.area} className={s.windRow} data-row="" data-force={w.force} style={vars(axes(w.force))}>
          <span className={s.windArea}>{w.area}</span>
          <span className={s.windText} data-gale={w.force >= 8 || undefined}>
            <svg className={s.arrow} viewBox="0 0 24 24" aria-hidden="true" focusable="false" style={{ rotate: `${w.from + 180}deg` }}>
              <path d="M12 3v18M12 3l-6 7M12 3l6 7" />
            </svg>
            {w.wind}
          </span>
        </li>
      ))}
    </ol>
  );
}

/** A static specimen strip: the same two letters at forces 2–9. */
export function ForceScale() {
  return (
    <figure className={s.scale}>
      <div className={s.scaleRow} aria-hidden="true">
        {[2, 3, 4, 5, 6, 7, 8, 9].map((f) => (
          <span key={f} className={s.scaleCell}>
            <span className={s.scaleGlyph} style={vars(axes(f))}>Aa</span>
            <span className={s.scaleNum}>F{f}</span>
          </span>
        ))}
      </div>
      <figcaption className={s.scaleCap}>Weight, width and optical size follow the wind force: light and wide is calm, heavy and narrow is a gale. Every row also states its force in words.</figcaption>
    </figure>
  );
}
